#!/usr/bin/env bash
# Server-owned preview-8768 deployment jobs (Phase 5).
#
#   deploy_job_8768.sh start    <40-char commit> <job id>
#   deploy_job_8768.sh status   <job id> <40-char commit>
#   deploy_job_8768.sh recover  <job id> <40-char commit>
#   deploy_job_8768.sh rollback <job id> <40-char commit>
#
# `start` launches deploy_preview_8768.sh DETACHED (own session via setsid,
# nohup, SIGHUP ignored, stdin from /dev/null, no inherited lock fd), so an
# SSH disconnect, closed terminal or interrupted PowerShell cannot stop it.
#
# Job ids are canonical lowercase UUIDs generated by the client; the id IS the
# job: repeating `start` never launches a second installation. Every job is
# BOUND to its exact commit: status/recover/rollback must name the same
# commit, and reusing an id with another commit is refused (SHA_MISMATCH).
#
# Job creation is atomic: creation, recovery and rollback launches run under
# a short jobs.lock, the job directory is built privately and renamed into
# place (never seen half-written), and the lock is held until the job's pid
# is recorded, so simultaneous requests see the running job and start nothing.
# Status, result and log are private (0700, files 0600); the orchestrator
# prints no environment or credentials. The exclusive deployment lock itself
# is held by deploy_preview_8768.sh for install, verification and rollback.
set -Euo pipefail
umask 077
trap '' HUP
readonly STATE_ROOT=${PREVIEW_STATE_ROOT:-/home/opc/.kalshi-deploy/preview-8768}
readonly JOBS=$STATE_ROOT/jobs
readonly JOBS_LOCK=$STATE_ROOT/jobs.lock
readonly SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
readonly ORCHESTRATOR=$SCRIPT_DIR/deploy_preview_8768.sh

say() { printf 'DEPLOY_JOB: %s\n' "$*"; }
reject() { say "$1"; printf 'DEPLOY_JOB_STATE=%s\n' "${2:-REJECTED}"; exit 2; }
valid_id() { [[ $1 =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]]; }
valid_sha() { [[ $1 =~ ^[0-9a-f]{40}$ ]]; }

# Serialise job creation/launch decisions (fd 8; never the deployment lock).
jobs_lock() {
  install -d -m 0700 "$STATE_ROOT" "$JOBS" || return 1
  exec 8>>"$JOBS_LOCK" || return 1
  chmod 0600 "$JOBS_LOCK"
  flock -w 30 8 || { say "job registry is busy"; return 1; }
}

job_pid_alive() {
  local job=$1 pid
  [[ -f $job/pid ]] || return 1
  pid=$(<"$job/pid")
  [[ $pid =~ ^[0-9]+$ ]] && kill -0 "$pid" 2>/dev/null &&
    tr '\0' ' ' <"/proc/$pid/cmdline" 2>/dev/null | grep -q 'deploy_preview_8768.sh'
}

active_job() {
  local job
  for job in "$JOBS"/*/; do
    [[ -d $job ]] || continue
    job=${job%/}
    [[ $(basename "$job") == .* ]] && continue
    [[ -f $job/result ]] && continue
    if job_pid_alive "$job"; then basename "$job"; return 0; fi
  done
  return 1
}

# Refuse any operation whose commit is not the job's own commit.
require_bound() {
  local job=$1 sha=$2
  [[ -f $job/sha && $(<"$job/sha") == "$sha" ]] ||
    reject "job $(basename "$job") is bound to a different commit; nothing was done" SHA_MISMATCH
}

emit_status() {
  local id=$1 job=$JOBS/$1 state
  if [[ -f $job/result ]]; then state=FINISHED
  elif job_pid_alive "$job"; then state=RUNNING
  elif [[ -f $job/pid ]]; then state=DIED
  else state=STARTING
  fi
  printf 'DEPLOY_JOB_ID=%s\nDEPLOY_JOB_STATE=%s\n' "$id" "$state"
  [[ -f $job/sha ]] && printf 'DEPLOY_JOB_SHA=%s\n' "$(<"$job/sha")"
  [[ -f $job/run_id ]] && printf 'DEPLOY_RUN_ID=%s\n' "$(<"$job/run_id")"
  [[ -f $job/result ]] && grep -E '^(DEPLOY_RESULT|EXIT|FINISHED_AT)=' "$job/result"
  # Recent progress (the orchestrator never prints environment or secrets).
  [[ -f $job/log ]] && tail -n 20 "$job/log" | sed 's/^/LOG: /'
  return 0
}

launch() {
  local job=$1; shift
  rm -f "$job/pid" "$job/result"
  # Own session, no terminal, no SIGHUP, neither lock fd (8 or 9) inherited.
  setsid nohup env PREVIEW_JOB_DIR="$job" bash "$ORCHESTRATOR" "$@" \
    >>"$job/log" 2>&1 </dev/null 8>&- 9>&- &
  for _ in $(seq 50); do [[ -f $job/pid ]] && break; sleep 0.1; done
}

cmd=${1:-}
case $cmd in
  start)
    sha=${2:-}; id=${3:-}
    valid_sha "$sha" || reject "an exact 40-character commit is required"
    valid_id "$id" || reject "invalid job id (a lowercase UUID is required)"
    jobs_lock || reject "could not lock the job registry; nothing was started" BUSY
    if [[ -d $JOBS/$id ]]; then
      require_bound "$JOBS/$id" "$sha"
      say "job $id already exists for this commit; reporting it (no second installation)"
      emit_status "$id"; exit 0
    fi
    if other=$(active_job); then
      say "another deployment job is running: $other; nothing was started"
      printf 'DEPLOY_JOB_STATE=BUSY\nDEPLOY_ACTIVE_JOB=%s\n' "$other"; exit 0
    fi
    # Build privately, then publish with one rename: never half-written.
    tmp=$(mktemp -d "$JOBS/.new-XXXXXX")
    chmod 0700 "$tmp"
    printf '%s\n' "$sha" >"$tmp/sha"
    date -u +%Y-%m-%dT%H:%M:%SZ >"$tmp/created_at"
    : >"$tmp/log"
    chmod 0600 "$tmp/sha" "$tmp/created_at" "$tmp/log"
    mv -T -n "$tmp" "$JOBS/$id" 2>/dev/null
    if [[ -d $tmp ]]; then rm -rf -- "$tmp"; reject "job $id could not be created atomically; nothing was started"; fi
    launch "$JOBS/$id" deploy "$sha"
    emit_status "$id" ;;
  status)
    id=${2:-}; sha=${3:-}
    valid_id "$id" || reject "invalid job id (a lowercase UUID is required)"
    valid_sha "$sha" || reject "the job's 40-character commit is required"
    [[ -d $JOBS/$id ]] || reject "unknown job" UNKNOWN
    require_bound "$JOBS/$id" "$sha"
    emit_status "$id" ;;
  recover|rollback)
    id=${2:-}; sha=${3:-}; job=$JOBS/$id
    valid_id "$id" || reject "invalid job id (a lowercase UUID is required)"
    valid_sha "$sha" || reject "the job's 40-character commit is required"
    [[ -d $job ]] || reject "unknown job" UNKNOWN
    require_bound "$job" "$sha"
    jobs_lock || reject "could not lock the job registry; nothing was started" BUSY
    if job_pid_alive "$job"; then say "job is still running; nothing started"; emit_status "$id"; exit 0; fi
    if [[ $cmd == recover ]]; then
      if [[ -f $job/result ]]; then say "job is not interrupted; nothing to recover"; emit_status "$id"; exit 0; fi
      if [[ ! -f $job/run_id ]]; then
        # Interrupted before the snapshot: the installer had not started.
        printf 'DEPLOY_RESULT=INTERRUPTED_BEFORE_CHANGE\nEXIT=2\nFINISHED_AT=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >"$job/result.next"
        chmod 0600 "$job/result.next"; mv -f "$job/result.next" "$job/result"
        emit_status "$id"; exit 0
      fi
      say "recovering interrupted job $id under the exclusive lock (detached)"
      launch "$job" recover "$sha" "$(<"$job/run_id")"
    else
      if ! grep -qx 'DEPLOY_RESULT=SUCCESS' "$job/result" 2>/dev/null || [[ ! -f $job/run_id ]]; then
        say "only a successful job can be rolled back by request; nothing started"; emit_status "$id"; exit 0
      fi
      launch "$job" rollback "$sha" "$(<"$job/run_id")"
    fi
    emit_status "$id" ;;
  *) echo "usage: $0 start <commit> <id> | status|recover|rollback <id> <commit>" >&2; exit 2 ;;
esac
